from pathlib import Path
import json
import base64
import re

ROOT = Path(__file__).parent
header = '''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>拾传 · 三端界面设计</title><style>
*{box-sizing:border-box}body{margin:0;background:#e9eeeb;color:#183d35;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}button,input{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #176b55;outline-offset:4px}button{transition:background .15s}button:hover{filter:brightness(.97)}[hidden]{display:none!important}.review-header{padding:44px 40px 24px;max-width:1500px;margin:auto}.eyebrow{font:12px monospace;letter-spacing:.13em;color:#596d65}.review-header h1{font-size:44px;letter-spacing:-.04em;margin:16px 0}.review-header p{max-width:760px;font-size:16px;line-height:1.8;color:#596d65}.review-header a{color:#176b55}.review-meta{display:flex;gap:8px;flex-wrap:wrap}.review-meta span{padding:8px 12px;background:#dce6df;border-radius:30px;font-size:12px}.review-toolbar{display:flex;gap:8px;flex-wrap:wrap;padding:16px 40px;background:#e9eeeb;border-bottom:1px solid #cbd8ce;position:sticky;top:0;z-index:30}.review-toolbar button{border:1px solid #becdc3;background:transparent;color:#183d35;border-radius:24px;padding:11px 18px;min-height:44px}.review-toolbar button[aria-pressed=true]{background:#183d35;color:white;border-color:#183d35}.review-toolbar .return{margin-left:auto}.gallery{display:flex;flex-wrap:wrap;align-items:flex-start;gap:40px;padding:40px;max-width:2400px;margin:auto}.board{flex:0 0 auto;scroll-margin-top:100px;max-width:100%}.board-label{font-size:13px;font-weight:600;line-height:1.5;margin-bottom:12px;color:#425c50}.screen{box-shadow:0 12px 30px #183d3512;overflow:hidden}.board-note{font-size:12px;line-height:1.7;color:#596d65;max-width:390px}.review-notes{margin:0 40px 40px;padding:24px;background:#f7faf8;border:1px solid #cbd8ce;border-radius:16px;line-height:1.9;max-width:1100px}.review-notes h2{font-size:20px}.review-notes td,.review-notes th{text-align:left;padding:12px;border-bottom:1px solid #e5efe9;vertical-align:top}.review-notes a{color:#176b55}.toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);max-width:calc(100% - 32px);background:#183d35;color:white;padding:14px 22px;border-radius:12px;z-index:100;font-size:14px;box-shadow:0 8px 32px #0002}.focused .review-header,.focused .review-notes{display:none}.focused .gallery{justify-content:center}@media(max-width:650px){.review-header{padding:28px 20px}.review-header h1{font-size:32px}.review-toolbar{padding:12px 16px}.gallery{padding:24px 12px;gap:32px;overflow:auto;justify-content:flex-start}.review-notes{margin:0 12px 24px}.board{max-width:none}.review-header p{font-size:14px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}@media print{.review-toolbar,.review-header,.review-notes,.toast{display:none}.gallery{display:block;padding:0}.board{break-inside:avoid;page-break-after:always;margin-bottom:40px}.screen{box-shadow:none}}
</style></head><body><header class="review-header"><div class="eyebrow">PICKDROP / UI REDESIGN / 2026.10.11</div><h1>拾传，轻一点。</h1><p>保留随手拖入的小窗与动物群头像。让每次传输的状态更清楚，让电脑、手机和终端使用同一套语言。</p><div class="review-meta"><span>三位子代理协作审查</span><span>雪松 · 高对比 · 少装饰</span><span>界面提案 / 演示数据</span></div><p><a href="https://app.paper.design/file/01M4NNKDA0MHR7XVKC7BR8KPD2" target="_blank" rel="noopener">打开 Paper 设计文件 ↗</a>　Paper 周额度耗尽，完整方案以此本地稿为准。界面操作为演示，不会实际发送或删除文件。</p></header><nav class="review-toolbar" aria-label="查看平台"><button data-filter="all" aria-pressed="true">全部界面</button><button data-filter="desktop" aria-pressed="false">电脑</button><button data-filter="mobile" aria-pressed="false">手机</button><button data-filter="terminal" aria-pressed="false">终端</button><button class="return" id="overview">返回总览</button></nav><main class="gallery" id="gallery">'''
footer = '''</main><section class="review-notes"><h2>这次优先解决什么</h2><table><thead><tr><th>平台</th><th>当前问题</th><th>设计改动</th></tr></thead><tbody><tr><td>电脑</td><td>发送失败条目消失；小字号；操作层级混杂。</td><td>保留失败卡片与重试；正文提升到14px；群操作与设备设置分离。</td></tr><tr><td>手机</td><td>辅助文字对比度低至2.33:1；首页头部拥挤；文件保存入口较深。</td><td>文字对比度提升；加入成为主操作；文件卡直接保存；传输入口常驻。</td></tr><tr><td>终端</td><td>80×24头尾占7行；发文件快捷键不可见；发送按钮在目录末尾。</td><td>缩短头尾；固定快捷键；已选文件汇总与发送始终可见。</td></tr></tbody></table><p><strong>方案边界：</strong>桌面统一使用小窗。常驻传输页与部分导航为新增设计建议。现有功能仍以实际客户端为准；不包含暂停传输、断点续传或全员离线投递。手机原生权限、键盘弹起与系统分享需在实施后真机验证。</p><p>详细审查：<a href="desktop-audit.md">电脑</a> · <a href="mobile-audit.md">手机</a> · <a href="tui-audit.md">终端</a></p></section><div class="toast" id="toast" role="status" hidden></div><dialog id="cleanup-dialog" style="border:1px solid #D5E2DA;border-radius:20px;padding:28px;width:360px;max-width:calc(100% - 32px);color:#183D35"><h2 style="margin:0 0 16px;font-size:22px">清理缓存</h2><p id="cleanup-description" style="line-height:1.7;color:#596D65"></p><form method="dialog" style="display:flex;justify-content:flex-end;gap:12px;margin-top:24px"><button style="padding:12px 18px;border:1px solid #D5E2DA;border-radius:10px;background:white" autofocus>取消</button><button style="padding:12px 18px;border:0;border-radius:10px;background:#176B55;color:white">清理</button></form></dialog><script>
const boards=[...document.querySelectorAll('.board')];let toastTimer;
function overview(filter='all'){document.body.classList.remove('focused');boards.forEach(b=>b.hidden=filter!=='all'&&b.dataset.platform!==filter);document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));}
function focusBoard(id){const board=document.getElementById(id);if(!board)return;document.body.classList.add('focused');boards.forEach(b=>b.hidden=b!==board);window.scrollTo({top:0});}
document.addEventListener('click',e=>{const filter=e.target.closest('[data-filter]');if(filter){overview(filter.dataset.filter);return;}const target=e.target.closest('[data-target]');if(target&&document.getElementById(target.dataset.target)){focusBoard(target.dataset.target);return;}const action=e.target.closest('[data-action]');if(action){if(/清理|缓存/.test(action.dataset.action)){const modal=document.getElementById('cleanup-dialog');const copies=/副本/.test(action.dataset.action);modal.querySelector('h2').textContent=copies?'清理本机副本':'清理缓存';document.getElementById('cleanup-description').textContent=copies?'清理最后一份副本后，其他设备将无法下载。':'已另存的文件不受影响，正在使用的文件将保留。';modal.showModal();return;}let toast=document.getElementById('toast');toast.textContent='设计演示：'+action.dataset.action;toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.hidden=true,3500);}});
document.getElementById('overview').onclick=()=>overview();document.addEventListener('keydown',e=>{if(e.key==='Escape'){overview();document.getElementById('toast').hidden=true;}});
document.querySelectorAll('[data-filter]').forEach(b=>{let n=b.dataset.filter==='all'?boards.length:boards.filter(x=>x.dataset.platform===b.dataset.filter).length;b.textContent+=' · '+n;});
</script></body></html>'''
parts = [ROOT.joinpath(name+'-boards.html').read_text() for name in ['desktop','mobile','tui']]
document = header+'\n'.join(parts)+footer
def embed(match):
    source = (ROOT / match.group(1)).resolve()
    if not source.is_file():
        return match.group(0)
    mime = 'image/svg+xml' if source.suffix == '.svg' else 'image/png'
    return 'src="data:'+mime+';base64,'+base64.b64encode(source.read_bytes()).decode()+'"'
document = re.sub(r'src="(\.\./[^\"]+)"', embed, document)
ROOT.joinpath('index.html').write_text(document)
print(ROOT/'index.html')
